workID.script:
extends RefCounted
func tap(tree:SceneTree,at:Vector2)->void:
	var event=InputEventScreenTouch.new()
	event.position=at
	event.pressed=true
	Input.parse_input_event(event)
	await tree.process_frame
	event=InputEventScreenTouch.new()
	event.position=at
	event.pressed=false
	Input.parse_input_event(event)
	await tree.process_frame
func execute(tree:SceneTree)->Variant:
	var menu=tree.current_scene.get_meta("identity_menu")
	var page=menu._identity_page
	await tap(tree,page._align_button.get_global_rect().get_center())
	await tree.process_frame
	var entered=page._portrait._placing
	var rect=page._portrait.image_rect()
	var normalized=PackedVector2Array([Vector2(.391,.387),Vector2(.574,.354),Vector2(.504,.578)])
	for point in normalized:
		await tap(tree,page._portrait.get_global_transform()*(rect.position+point*rect.size))
	var saved=tree.current_scene.get_meta("identity_fixture").accepted
	var matches=saved.size()==3
	if matches:
		for i in saved.size():matches=matches and saved[i].is_equal_approx(normalized[i])
	return {"entered_by_real_touch":entered,"three_points_match":matches,"status":page._status.text,"complete":not page._portrait._placing,"save":tree.root.get_texture().get_image().save_png("/data/data/com.termux/files/usr/tmp/scraperx-portable-line-20261020/character-prototype/work-id-touch.png"),"scope":"engine-routed touch through Work ID UI with memory fixture, not native OS photo picker"}

integration.script:
extends RefCounted
func execute(tree: SceneTree) -> Variant:
	var main: Node = load("res://main.tscn").instantiate()
	main.prepare_initial_world = false
	main._settings_persistent = false
	main._force_touch = true
	tree.root.add_child(main)
	main.set_process(false)
	var actor: Dictionary = main._native.get_story_actor_state()
	var staged: bool = main._native.debug_restart_at(actor.position + Vector3(0,0,.95))
	for i in 60:
		main._process(1.0/90.0)
	actor = main._native.get_story_actor_state()
	tree.set_meta("actor_main", main)
	return {"staged":staged,"supported":actor.supported,"visible":main._story_human.visible,"gait_ready":main._story_human._gait.last_error.is_empty(),"episode":actor.episode,"soles_error_m":main._story_human.global_position.distance_to(actor.position-Vector3(0,.9,0))}
